    '''        .quoteHeadingEditing {\n          background: #fff;\n        }''',
    '''        .quoteHeadingEditing {\n          background: #fff;\n        }\n        .quotePresentationPanel {\n          margin: 0 18px 12px 70px;\n          padding: 12px;\n          border: 1px solid #d7cfed;\n          border-radius: 9px;\n          background: #fbfaff;\n        }\n        .quotePresentationHeader,\n        .quotePhotosTop,\n        .quoteStyleActions,\n        .quoteStyleToggles,\n        .quoteHighlightControl,\n        .quotePhotoMeta label {\n          display: flex;\n          align-items: center;\n        }\n        .quotePresentationHeader,\n        .quotePhotosTop {\n          justify-content: space-between;\n          gap: 12px;\n        }\n        .quotePresentationHeader > div,\n        .quotePhotosTop > div {\n          display: grid;\n          gap: 2px;\n        }\n        .quotePresentationHeader small,\n        .quotePhotosTop small {\n          color: var(--muted);\n          font-size: 9px;\n        }\n        .quoteStyleEditor {\n          display: grid;\n          grid-template-columns: minmax(130px, 1fr) 90px 90px minmax(150px, 1fr) auto minmax(130px, 1fr);\n          gap: 9px;\n          align-items: end;\n          margin-top: 10px;\n        }\n        .quoteStyleEditor > label {\n          display: grid;\n          gap: 4px;\n          color: var(--muted);\n          font-size: 9px;\n          font-weight: 800;\n          text-transform: uppercase;\n        }\n        .quoteStyleEditor select {\n          height: 30px;\n          border: 1px solid #d7cfed;\n          border-radius: 6px;\n          background: #fff;\n          color: var(--text);\n        }\n        .quoteColorControl input[type="color"],\n        .quoteHighlightControl input[type="color"] {\n          width: 38px;\n          height: 30px;\n          padding: 2px;\n          border: 1px solid #d7cfed;\n          border-radius: 6px;\n          background: #fff;\n        }\n        .quoteHighlightControl {\n          gap: 6px;\n          align-self: end;\n          height: 30px;\n        }\n        .quoteStyleToggles {\n          gap: 4px;\n        }\n        .quoteStyleToggles button {\n          width: 30px;\n          height: 30px;\n          display: grid;\n          place-items: center;\n          border: 1px solid #d7cfed;\n          border-radius: 6px;\n          background: #fff;\n          cursor: pointer;\n        }\n        .quoteStyleToggles button.isActive {\n          border-color: #8c78c7;\n          background: #e9e2fb;\n          color: #4f3c93;\n        }\n        .quoteStylePreview {\n          min-height: 30px;\n          display: flex;\n          align-items: center;\n          width: fit-content;\n        }\n        .quoteStyleActions {\n          grid-column: 1 / -1;\n          gap: 6px;\n        }\n        .quoteStyleActions button,\n        .quotePhotoAddButton {\n          display: inline-flex;\n          align-items: center;\n          gap: 5px;\n          min-height: 30px;\n          padding: 0 9px;\n          border: 1px solid #d7cfed;\n          border-radius: 6px;\n          background: #fff;\n          color: #6554b5;\n          font-size: 10px;\n          font-weight: 800;\n          cursor: pointer;\n        }\n        .quotePhotosPanel {\n          margin-top: 12px;\n          padding-top: 12px;\n          border-top: 1px solid #e4def2;\n        }\n        .quotePhotoAddButton input {\n          display: none;\n        }\n        .quotePhotosEmpty {\n          margin-top: 9px;\n          color: var(--muted);\n          font-size: 10px;\n        }\n        .quotePhotoGrid {\n          display: grid;\n          grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));\n          gap: 8px;\n          margin-top: 9px;\n        }\n        .quotePhotoCard {\n          position: relative;\n          display: grid;\n          grid-template-columns: 78px 1fr;\n          gap: 8px;\n          align-items: center;\n          padding: 6px;\n          border: 1px solid #e4def2;\n          border-radius: 7px;\n          background: #fff;\n        }\n        .quotePhotoCard img {\n          width: 78px;\n          height: 58px;\n          object-fit: cover;\n          border-radius: 5px;\n          background: #f3f1f8;\n        }\n        .quotePhotoMeta {\n          min-width: 0;\n          display: grid;\n          gap: 7px;\n        }\n        .quotePhotoMeta strong {\n          overflow: hidden;\n          text-overflow: ellipsis;\n          white-space: nowrap;\n          font-size: 10px;\n        }\n        .quotePhotoMeta label {\n          gap: 5px;\n          font-size: 9px;\n          font-weight: 700;\n        }\n        .quotePhotoDelete {\n          position: absolute;\n          right: 4px;\n          top: 4px;\n          width: 24px;\n          height: 24px;\n          display: grid;\n          place-items: center;\n          padding: 0;\n          border: 1px solid #ead0d0;\n          border-radius: 6px;\n          background: #fff;\n          color: #a53d3d;\n          cursor: pointer;\n        }\n        .quotePresentationError {\n          margin-top: 9px;\n          color: #a53d3d;\n          font-size: 10px;\n          font-weight: 700;\n        }''',
